// ---------- time helpers ----------
const t = (s) => { const [h, m] = s.split(":").map(Number); return h * 60 + m; };
const DEFAULT_PARAMS = {
  dayStart: t("7:45"), dayEnd: t("15:45"), budgetMin: 480, transition: 3,
  planRatio: 15, creditWeeks: 32, setup: 5, teardown: 5, cleaning: 10, idle: 10,
};
const fmt = (min) => {
  if (min == null || isNaN(min)) return "—";
  let h = Math.floor(min / 60), m = min % 60;
  const ap = h >= 12 ? "PM" : "AM";
  h = h % 12 || 12;
  return `${h}:${String(m).padStart(2, "0")} ${ap}`;
};
const toInput = (min) => {
  if (min == null || isNaN(min) || min < 0) return "";
  return `${String(Math.floor(min / 60)).padStart(2, "0")}:${String(min % 60).padStart(2, "0")}`;
};
const blockHasTime = (b) => b && b.start != null && b.end != null && !isNaN(b.start) && !isNaN(b.end) && b.start >= 0 && b.end >= 0;
const sortBlocksForDay = (a, b) => {
  const aHas = blockHasTime(a);
  const bHas = blockHasTime(b);
  if (aHas && !bHas) return -1;
  if (!aHas && bHas) return 1;
  if (!aHas && !bHas) return 0;
  return a.start - b.start;
};
const overlap = (a, b) => {
  if (!blockHasTime(a) || !blockHasTime(b)) return false;
  return a.start < b.end && b.start < a.end;
};
const shareDay = (a, b) => a.days.some((d) => b.days.includes(d));
const pickBestPlan = (list) => {
  if (!list || !list.length) return null;
  return list.reduce((a, b) => {
    const aBlocks = (a.blocks || []).length;
    const bBlocks = (b.blocks || []).length;
    if (aBlocks && !bBlocks) return a;
    if (bBlocks && !aBlocks) return b;
    return (a.updatedAt || "") >= (b.updatedAt || "") ? a : b;
  }, list[0]);
};

