function nextBlockId() {
  return `b${Date.now()}${Math.floor(Math.random() * 1000)}`;
}

function blankBlock(band, day) {
  return {
    id: nextBlockId(),
    band,
    course: "",
    subject: "",
    days: [day],
    start: null,
    end: null,
    teacher: null,
    teacher2: null,
    room: "",
    grades: (BAND_GRADES[band] || []).slice(),
  };
}

